export type Transition =
  | 'blurReplace'
  | 'identity'
  | 'opacity'
  | 'scale'
  | 'slide'
  | 'symbolEffect'
  | { blurReplace: BlurReplaceTransitionConfiguration }
  | { move: { edge: Edge } }
  | { offset: { x?: number; y?: number } }
  | { offset: CGSize }
  | { push: { from: Edge } }
  | { scale: { scale: number; anchor?: UnitPoint } }
  | TransitionChain;

/** `Transition` with chained calls: `SwiftUI.Transition.animation(...)`. */
export interface TransitionChain<Value = any> {
  readonly $base: unknown;
  readonly $calls: readonly unknown[];
  animation(animation: Animation | null): TransitionChain<Value>;
  combined(options: { with: Transition }): TransitionChain<Value>;
}

